const data = $json.body || $json;

// 1. Extract and sanitize inputs
const full_Name = String(data.full_name ?? "").trim();
const email = String(data.email ?? "").trim();
const company = String(data.company ?? "").trim();
const job_title = $json.job_title || $json.body?.job_title || "";
const source = $json.source ||$json.body?.source || "";

const interested_in = String(data.interested_in ?? "").trim();
const message = String(data.message ?? "").trim();

// 2. Define allowed values for 'Interested In' (adjust to match your Airtable options)
const allowedinterested_in = [

  "Web Development",
  "Automation",
  "AI & Solutions",

  "Other"
];

// 3. Perform basic validation checks
const isFullNameValid = full_Name.length > 0;
const isEmailValid = email.length > 0 && email.includes("@");
const isCompanyValid = company.length > 0;
const isinterested_inValid = allowedinterested_in.includes(interested_in);
const isMessageValid = message.length > 0;

const isValid = isFullNameValid && isEmailValid && isCompanyValid && isinterested_inValid && isMessageValid;

// 4. Return processed fields and Airtable routing flags
return {
  full_Name,
  email,
  company,
  job_title,
  source,
  interested_in,
  message,
  isValid,
  status: "New",
  followUp: isValid ? "" : "Missing required information"
};

