const root = $input.first().json;
let ai = root && root.output && root.output[0] && root.output[0].content && root.output[0].content[0]
  ? root.output[0].content[0].text
  : undefined;
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = {}; } }
if (!ai || typeof ai !== 'object') { ai = {}; }
const ai_category = ai.ai_category || 'Low-Intent';
const priority = ai.priority || 'Low';
const ai_reason = ai.ai_reason || 'No reason provided.';
let status, assigned_team, follow_up;
if (priority === 'High') {
  status = 'Qualified'; assigned_team = 'Sales Team'; follow_up = 'Contact the lead as soon as possible';
} else if (priority === 'Medium') {
  status = 'Contacted'; assigned_team = 'Sales Team'; follow_up = 'Contact the lead within 3 days';
} else {
  status = 'New'; assigned_team = 'Marketing Team'; follow_up = 'Add the lead to the marketing follow-up list';
}
return [{ ai_category, priority, ai_reason, status, assigned_team, follow_up }];

